/* CSS for Elementor Custom CSS Section */
.mega-clients-section {
    padding: 3rem 0;
    background: #f8f9fa;
}

.clients-title {
    text-align: center;
    font-size: 2.5rem;
    font-weight: 700;
    color: #2c3e50;
    margin-bottom: 3rem;
    position: relative;
}

.clients-title::after {
    content: '';
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 80px;
    height: 4px;
    background: #7cb342;
    border-radius: 2px;
}

.clients-container {
    overflow: hidden;
    position: relative;
    background: #ffffff;
    padding: 2rem 0;
    border-radius: 12px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    margin: 0 2rem;
}

.clients-track {
    display: flex;
    gap: 1.5rem;
    transition: transform 0.1s linear;
}

.client-logo {
    background: #ffffff;
    padding: 1rem;
    border-radius: 12px;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    transition: all 0.3s ease;
    width: 180px;
    height: 120px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #f8f9fa;
    flex-shrink: 0;
    overflow: hidden;
}

.client-logo img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    transition: all 0.3s ease;
    filter: grayscale(20%);
}

.client-logo:hover {
    transform: scale(1.05);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
    border-color: #7cb342;
}

.client-logo:hover img {
    transform: scale(1.1);
    filter: grayscale(0%);
}

/* Mobile Responsive */
@media (max-width: 768px) {
    .clients-container {
        margin: 0 1rem;
    }

    .clients-title {
        font-size: 2rem;
        margin-bottom: 2rem;
    }

    .client-logo {
        width: 150px;
        height: 100px;
    }
}

@media (max-width: 480px) {
    .client-logo {
        width: 120px;
        height: 80px;
        padding: 0.5rem;
    }

    .clients-track {
        gap: 1rem;
    }
}

.kc-carousel-images .item:nth-child(2),
.kc-carousel-images .item:nth-child(3),
.kc-carousel-images .item:nth-child(4) {
    display: none !important;
}

.kc-row-container:not(.kc-container) {
    padding: 0 !important;
}
#blog-area {
    padding: 0px 0 0px;
}

/* ================================
   GLOBAL CONTENT STYLING
================================ */
.kc_column_text {
    font-size: 16px;
    line-height: 1.8;
    color: #333;
    background: #f9fafb;
    padding: 25px;
    border-radius: 16px;
}

.kc_column_text p {
    margin-bottom: 18px;
}

/* ================================
   SECTION HEADINGS (H2)
================================ */
.kc_title h2 {
    font-size: 32px;
    font-weight: 700;
    color: #0a3d62;
    letter-spacing: 1px;
    position: relative;
    margin-bottom: 30px;
}

/* Gradient underline */
.kc_title h2::after {
    content: "";
    display: block;
    width: 90px;
    height: 4px;
    background: linear-gradient(90deg, #0a3d62, #38ada9);
    margin-top: 12px;
}

/* Center aligned title fix */
.kc_title.text-center h2::after {
    margin-left: auto;
    margin-right: auto;
}

/* ================================
   IMAGE STYLING
================================ */
.kc_single_image img {
    width: 100%;
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.15);
    transition: transform 0.4s ease;
}

.kc_single_image img:hover {
    transform: scale(1.03);
}

/* ================================
   EQUIPMENT LIST STYLING
================================ */
.kc_column_text br {
    line-height: 2.2;
}

/* Add check icon before each line */
.kc_column_text {
    position: relative;
}

.kc_column_text::after {
    content: "";
    display: block;
    clear: both;
}

/* ================================
   SALIENT FEATURES HIGHLIGHT
================================ */
.kc_column_text strong {
    color: #0a3d62;
    font-weight: 600;
}

/* ================================
   INDUSTRIAL CARD EFFECT
================================ */
.kc_row {
    margin-bottom: 40px;
}

.kc_column {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.kc_column:hover {
    transform: translateY(-6px);
}

/* ================================
   RESPONSIVE DESIGN
================================ */
@media (max-width: 768px) {

    .kc_title h2 {
        font-size: 26px;
        text-align: center;
    }

    .kc_column_text {
        font-size: 15px;
        padding: 18px;
    }

    .kc_single_image img {
        border-radius: 12px;
    }
}

.mega-img {
  margin: 25px 0;
  box-shadow: 0 15px 40px rgba(0,0,0,0.18);
}

.mega-img:hover {
  transform: scale(1.04);
  box-shadow: 0 30px 70px rgba(0,0,0,0.35);
}
/* ===============================
   GLOBAL VARIABLES
================================ */
:root {
  --mega-primary: #0a3d62;
  --mega-accent: #1e90ff;
  --mega-light: #f5f9fc;
  --mega-dark: #1f2937;
}

/* ===============================
   HERO SECTION
================================ */
.mega-hero {
  padding: 80px 20px;
  background: linear-gradient(135deg, #0a3d62, #1e90ff);
  color: #fff;
  text-align: center;
  animation: megaFadeUp 1s ease forwards;
}

.mega-hero .mega-heading {
  font-size: clamp(28px, 5vw, 48px);
  font-weight: 700;
  margin-bottom: 15px;
}

.mega-hero .mega-text {
  font-size: clamp(16px, 2.5vw, 20px);
  opacity: 0.95;
}

/* ===============================
   SECTIONS
================================ */
.mega-section {
  padding: 60px 20px;
  max-width: 1200px;
  margin: auto;
  animation: megaFadeUp 0.8s ease forwards;
}

/* ===============================
   HEADINGS
================================ */
.mega-heading {
  font-size: clamp(22px, 4vw, 32px);
  color: var(--mega-primary);
  margin-bottom: 15px;
  position: relative;
}

.mega-heading::after {
  content: "";
  width: 60px;
  height: 3px;
  background: var(--mega-accent);
  display: block;
  margin-top: 8px;
}

/* ===============================
   TEXT
================================ */
.mega-text {
  color: #4b5563;
  line-height: 1.7;
  font-size: 16px;
}

/* ===============================
   CARDS / BOXES
================================ */
.mega-card {
  background: #fff;
  padding: 25px;
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  transition: all 0.35s ease;
  height: 100%;
}

.mega-card:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 18px 45px rgba(0,0,0,0.15);
}

/* ===============================
   LISTS
================================ */
.mega-list {
  list-style: none;
  padding: 0;
}

.mega-list li {
  padding: 10px 0 10px 30px;
  position: relative;
  color: #374151;
}

.mega-list li::before {
  content: "✔";
  position: absolute;
  left: 0;
  color: var(--mega-accent);
  font-weight: bold;
}

/* ===============================
   CTA SECTION
================================ */
.mega-cta {
  background: var(--mega-light);
  padding: 50px 20px;
  text-align: center;
  border-radius: 18px;
}

.mega-cta a {
  display: inline-block;
  padding: 14px 28px;
  background: var(--mega-primary);
  color: #fff;
  border-radius: 30px;
  text-decoration: none;
  font-weight: 600;
  transition: all 0.3s ease;
}

.mega-cta a:hover {
  background: var(--mega-accent);
  transform: scale(1.05);
}

/* ===============================
   ANIMATIONS
================================ */
@keyframes megaFadeUp {
  from {
    opacity: 0;
    transform: translateY(25px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ===============================
   RESPONSIVE
================================ */
@media (max-width: 768px) {
  .mega-hero {
    padding: 60px 15px;
  }

  .mega-section {
    padding: 40px 15px;
  }

  .mega-card {
    padding: 20px;
  }
}

/* CRITICAL: Break out of WordPress theme containers */
.wp-block-html {
  width: 100vw;
  position: relative;
  left: 50%;
  right: 50%;
  margin-left: -50vw;
  margin-right: -50vw;
  max-width: 100vw;
  overflow-x: hidden;
}

/* Reset any theme padding/margins on your sections */
.hero-slider,
.tagline-section,
.section,
.cta-section,
.clients-section {
  margin-left: 0 !important;
  margin-right: 0 !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  max-width: 100% !important;
  width: 100% !important;
}

/* Ensure containers inside YOUR code work correctly */
.container {
  max-width: min(1400px, 90vw) !important;
  margin: 0 auto !important;
  padding: 0 clamp(15px, 3vw, 40px) !important;
  width: 100% !important;
}

.container-fluid {
  width: 100% !important;
  padding: 0 clamp(15px, 3vw, 40px) !important;
  max-width: 100vw !important;
}

/* Fix theme interference with your grids */
.services-grid,
.about-grid,
.values-grid,
.choose-grid,
.case-studies-grid,
.projects-grid,
.stats-grid,
.experience-grid,
.contact-grid {
  margin-left: 0 !important;
  margin-right: 0 !important;
}

/* Prevent theme from adding unwanted spacing */
.wp-block-html > *:first-child {
  margin-top: 0 !important;
}

.wp-block-html > *:last-child {
  margin-bottom: 0 !important;
}

/* Fix for Gutenberg editor blocks */
.block-editor-block-list__block[data-type="core/html"] {
  max-width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}


/* ========================================
   INSTANT FULL-WIDTH FIX FOR WORDPRESS
   ======================================== */

.mega-fullwidth-wrapper {
  width: 100vw !important;
  position: relative !important;
  left: 50% !important;
  right: 50% !important;
  margin-left: -50vw !important;
  margin-right: -50vw !important;
  max-width: none !important;
  overflow-x: hidden !important;
  padding: 0 !important;
}

/* Reset WordPress theme interference */
.mega-fullwidth-wrapper * {
  box-sizing: border-box !important;
}

/* Force all your sections to full width */
.mega-fullwidth-wrapper .hero-slider,
.mega-fullwidth-wrapper .tagline-section,
.mega-fullwidth-wrapper .section,
.mega-fullwidth-wrapper .cta-section,
.mega-fullwidth-wrapper .clients-section,
.mega-fullwidth-wrapper .about,
.mega-fullwidth-wrapper .values,
.mega-fullwidth-wrapper .services,
.mega-fullwidth-wrapper .case-studies,
.mega-fullwidth-wrapper .experience,
.mega-fullwidth-wrapper .projects,
.mega-fullwidth-wrapper .why-choose,
.mega-fullwidth-wrapper .testimonials {
  width: 100% !important;
  max-width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}

/* Fix WordPress block editor wrapper */
.wp-block-html {
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Remove theme container constraints */
body .site-content .wp-block-html,
body .content-area .wp-block-html,
body main .wp-block-html,
body article .wp-block-html {
  max-width: 100% !important;
  padding: 0 !important;
}

